// The metadata block of a generated reference page. The generator writes it as a fenced `yaml`
// block under the title and description, not as front matter: the "Generated" comment must stay
// the file's first line, and front matter is read only at byte 0. A page reads on GitHub as:
//
//   <!-- Generated by ... -->
//   # swarmops commit
//   Record a changeset ...
//   ```yaml
//   group: "write"
//   mutates: true
//   exit_codes: [0, 1, 2, 4, 5]
//   errors: [E_IDENTITY_REQUIRED, E_TOO_LARGE]
//   ```
//   ## Syntax
//
// The generator writes one flat `key: value` per line: a JSON string, a boolean, a number or a
// list of bare words and numbers. This parser reads that subset and nothing else.
export type MetaValue = string | number | boolean | Array<string | number>;
export type Meta = Record<string, MetaValue>;

const FENCE_OPEN = '```yaml';
const FENCE_CLOSE = '```';
const SECTION = '## ';
const LINE = /^([a-z_]+): (.*)$/;
const NUMBER = /^-?\d+$/;

/** One scalar: `"a \"b\""` -> a "b", `true` -> true, `4` -> 4, a bare word as it is. */
function scalar(text: string): string | number | boolean {
  if (text.startsWith('"')) {
    return JSON.parse(text) as string;
  }
  if (text === 'true' || text === 'false') {
    return text === 'true';
  }
  if (NUMBER.test(text)) {
    return Number(text);
  }
  return text;
}

/** One value: a scalar, or `[a, 1]` -> ['a', 1] (`[]` -> []). */
function value(text: string): MetaValue {
  if (!text.startsWith('[')) {
    return scalar(text);
  }
  const inner = text
    .slice(1, -1)
    .trim();
  if (inner === '') {
    return [];
  }
  return inner
    .split(',')
    .map((item) => scalar(item.trim()) as string | number);
}

/** The metadata of a reference page's Markdown, or null when it has no block before its first section. */
export function parseMeta(markdown: string): Meta | null {
  const lines = markdown.split('\n');

  // 1. The first `yaml` fence, if it comes before the first `## ` section.
  const open = lines.findIndex((line) => line === FENCE_OPEN || line.startsWith(SECTION));
  if (open === -1 || lines[open] !== FENCE_OPEN) {
    return null;
  }
  const close = lines.indexOf(FENCE_CLOSE, open + 1);
  if (close === -1) {
    return null;
  }

  // 2. One key per line; a line outside the subset is skipped, not guessed at.
  const meta: Meta = {};
  for (const line of lines.slice(open + 1, close)) {
    const match = LINE.exec(line);
    if (!match) {
      continue;
    }
    meta[match[1]] = value(match[2].trim());
  }
  return meta;
}

/** A string field, or '' when absent or not a string. */
export function metaText(meta: Meta, key: string): string {
  const v = meta[key];
  return typeof v === 'string' ? v : '';
}

/** A list field, as strings, or [] when absent. */
export function metaList(meta: Meta, key: string): string[] {
  const v = meta[key];
  return Array.isArray(v) ? v.map(String) : [];
}
